        "testata": "Al Jazeera",
        "lingua_originale": "en",
        "titolo_orig": "USA’s Pulisic shrugs off injury scare after 4-1 World Cup win over Paraguay",
        "testo_it": "Mondiali: Pulisic minimizza i timori per l'infortunio dopo la vittoria degli USA sul Paraguay per 4-1.",
        "priorita": "Media",
        "id_gruppo": 9,
